  `enabled` tinyint unsigned NOT NULL DEFAULT '1',
  `server_num` int unsigned NOT NULL DEFAULT '1',
  `vip` tinyint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
